    if not intervals:
        return []

    # Sort the intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = []
    for current in intervals:
        # If merged is empty or current start > last merged end, no overlap
        if not merged or current[0] > merged[-1][1]:
